    private async Task Guard(CoreScope s, Guid u, WatchProduction row, bool submission, CancellationToken ct)
    { if (row.State is "Cancelled" or "Withdrawn") throw new EvidenceBlockedException("WATCHProductionCancelledOrWithdrawn"); var snap = Read<WatchSnapshot>(row.SnapshotJson); await Source(s, snap, submission ? "Generate" : "Read", ct); if (submission && (!await db.WatchProfiles.AnyAsync(x => x.Id == row.ProfileId && x.Enabled, ct) || !await db.WatchTemplates.AnyAsync(x => x.Id == snap.Template.Id && x.ReviewStatus == "Approved", ct))) throw new EvidenceBlockedException("WATCHRendererOrTemplateDisabled"); if (!await db.WatchTemplates.AnyAsync(x => x.Id == snap.Template.Id && x.ReviewStatus == "Approved", ct)) throw new EvidenceBlockedException("WATCHTemplateWithdrawn"); if (submission && row.DeadlineUtc <= DateTimeOffset.UtcNow) throw new EvidenceBlockedException("WATCHDeadlineExceeded"); if (submission && Renderer(snap.Profile.Configuration.Renderer).Capabilities.Version != snap.Profile.Capabilities.Version) throw new EvidenceBlockedException("PinnedWATCHRendererVersionChanged"); foreach (var cast in snap.Cast) await MediaRightsGuard.Presentation(db, s, u, cast.Presentation.Id, "Reuse", ct); if (row.TimelineJson != null) foreach (var scene in Read<WatchTimeline>(row.TimelineJson).Scenes) await MediaRightsGuard.WatchVoice(db, s, u, scene, ct); }
    private async Task SceneIdentity(CoreScope s, Guid u, WatchSnapshot snap, WatchSceneInput input, MediaVersion version, bool voice, CancellationToken ct)
    {
        var package = await db.MediaPackages.AsNoTracking().SingleAsync(x => x.PresentationRevisionId == input.PresentationId && x.TenantId == s.TenantId && x.UniverseId == u, ct); var rules = Read<CharacterMediaRules>(package.SnapshotJson);
        if (version.Id == (voice ? rules.VoiceVersionId : rules.VisualVersionId) || rules.AdditionalVersionIds.Contains(version.Id)) return;
        var material = Read<MediaLibrary.Material>(version.SnapshotJson); if (!material.Request.GenerationId.HasValue) throw new EvidenceBlockedException("SceneAssetMustBelongToReviewedPresentationPackage");
        var run = Read<MediaGenerationSnapshot>((await db.MediaGenerations.AsNoTracking().SingleAsync(x => x.Id == material.Request.GenerationId, ct)).SnapshotJson);
        if (voice) await VoiceProfile(s, u, rules, (await db.MediaGenerations.AsNoTracking().SingleAsync(x => x.Id == material.Request.GenerationId, ct)).ProfileId, ct); else if (!run.Request.ReferenceVersionIds.Contains(rules.VisualVersionId)) throw new EvidenceBlockedException("SceneGenerationMustPreserveApprovedVisualReference");
    }
    private Task VoiceProfile(CoreScope s, Guid u, CharacterMediaRules rules, Guid proposed, CancellationToken ct) => MediaRightsGuard.VoiceProfile(db, s, u, rules, proposed, ct);
    private async Task<WatchMediaBinding[]> Bindings(Guid id, CancellationToken ct)
    { var stage = await db.WatchStages.AsNoTracking().Where(x => x.ProductionId == id && x.Kind == "Voice").SingleAsync(ct); if (stage.OutputJson != null) return Read<WatchMediaBinding[]>(stage.OutputJson); stage = await db.WatchStages.AsNoTracking().Where(x => x.ProductionId == id && x.Kind == "Assets").SingleAsync(ct); return stage.OutputJson == null ? [] : Read<WatchMediaBinding[]>(stage.OutputJson); }
