                        var run = await media.GenerateAsync(s, u, request with { OperationId = Derived(stage.Id, input.Key), Admission = new(production.Id, stage.Id) }, ct); job = run.Id;
                        if (run.State == "Failed") throw new EvidenceBlockedException("DependentMediaJobFailed: " + run.Outcome);
