                foreach (var input in snap.Request.Scenes)
                {
                    var b = bindings.Single(x => x.SceneKey == input.Key); var image = (await media.ExportAsync(s, u, b.ImageId!.Value, "Reuse", ct)).Version; var audio = (await media.ExportAsync(s, u, b.VoiceId!.Value, "Reuse", ct)).Version; MediaVersionView? music = input.MusicVersionId.HasValue ? (await media.ExportAsync(s, u, input.MusicVersionId.Value, "Reuse", ct)).Version : null; var text = snap.Script.Current!.Body.Substring(input.ScriptStart, input.ScriptLength); var row = await db.MediaVersions.AsNoTracking().SingleAsync(x => x.Id == audio.Id, ct); var source = Read<MediaLibrary.Material>(row.SnapshotJson); if (audio.GenerationId.HasValue) { var generation = Read<MediaGenerationSnapshot>((await db.MediaGenerations.AsNoTracking().SingleAsync(x => x.Id == audio.GenerationId, ct)).SnapshotJson); if (generation.Request.PromptOrText != text) throw new EvidenceBlockedException("SpokenMediaTextDoesNotMatchApprovedScene"); } else { MediaRules.Attest(audio.License.Kind == "Fixture" ? "Fixture" : "Manual", input.TranscriptEvidenceReference); }
