        { await Complete(s, u, stage.Id, token, stage.Kind.StartsWith("Render") && e is not (RuntimeConflictException or EvidenceBlockedException or RuntimeValidationException) ? "Unknown" : "Failed", null, null, e is EvidenceBlockedException or RightsBlockedException or RuntimeConflictException ? e.Message : e.GetType().Name, 0, CancellationToken.None); return true; }
    }
    private async Task Complete(CoreScope s, Guid u, Guid stage, Guid token, string state, object? output, string? resource, string? outcome, decimal cost, CancellationToken ct)
    { await Command(s, u, Guid.NewGuid(), "checkpoint", new { stage, token, state, resource, cost, outcome }, "Admin", async () => { var st = await db.WatchStages.SingleAsync(x => x.Id == stage && x.TenantId == s.TenantId && x.UniverseId == u, ct); var row = await Production(s, u, st.ProductionId, ct); if (row.State is "Cancelled" or "Withdrawn" || st.LeaseToken != token) return false; if (cost < 0 || cost > Read<WatchSnapshot>(row.SnapshotJson).Request.MaxMediaCost) throw new EvidenceBlockedException("WATCHPinnedBudgetExceeded"); st.State = state; st.ActualCost = cost; st.Outcome = outcome; st.ExternalResourceId ??= resource; st.LeaseToken = null; st.LeaseUntilUtc = null; if (state == "Waiting") st.NextUtc = DateTimeOffset.UtcNow.AddSeconds(2); if (output != null) st.OutputJson = Json(output); if (state is "Failed" or "Unknown") row.State = "Failed"; if (st.Kind == "Timing" && state == "Accepted") { row.TimelineJson = Json(output); foreach (var scene in Read<WatchTimeline>(row.TimelineJson).Scenes) { foreach (var version in new[] { scene.Image, scene.Voice, scene.Music }.Where(x => x != null).Select(x => x!)) { var reference = await db.Assets.AsNoTracking().SingleAsync(x => x.Id == version.AssetReferenceId, ct); db.Provenance.Add(new() { Id = Guid.NewGuid(), TenantId = s.TenantId, ContentRevisionId = row.CoreRevisionId, ParentRevisionId = reference.ContentRevisionId, Relation = "Adaptation" }); } } } if (st.Kind == "QA" && state == "Accepted") row.State = "Review"; return true; }, ct); }
    private async Task<WatchRenderRequest> RenderRequest(CoreScope s, Guid u, WatchProduction row, WatchStage stage, CancellationToken ct)
    { await Guard(s, u, row, false, ct); await WatchFence.VideoRights(db, s, row, "Generate", ct); var snap = Read<WatchSnapshot>(row.SnapshotJson); var timeline = Read<WatchTimeline>(row.TimelineJson!); var materials = new List<WatchRenderMaterial>(); foreach (var scene in timeline.Scenes) materials.Add(new(scene.Key, (await media.ExportAsync(s, u, scene.Image.Id, "Reuse", ct)).Bytes, (await media.ExportAsync(s, u, scene.Voice.Id, "Reuse", ct)).Bytes, scene.Music == null ? null : (await media.ExportAsync(s, u, scene.Music.Id, "Reuse", ct)).Bytes)); return new(stage.Id, snap.Profile.Configuration.AccountReference, snap.Profile.Configuration.Renderer, timeline, stage.Kind[6..], materials.ToArray()); }
    private async Task AcceptRender(CoreScope s, Guid u, Guid id, Guid token, WatchRenderResult result, CancellationToken ct)
    {
        var stage = await db.WatchStages.AsNoTracking().SingleAsync(x => x.Id == id, ct); var row = await Production(s, u, stage.ProductionId, ct); var snap = Read<WatchSnapshot>(row.SnapshotJson); if (result.Cost != 0 || result.RendererVersion != snap.Profile.Capabilities.Version || stage.ExternalResourceId != null && result.ResourceId != stage.ExternalResourceId) throw new RuntimeConflictException("OriginalRendererVersionResourceAndZeroCostRequired");
        if (result.State != "Completed" || result.Master == null || result.ResourceId == null) { await Complete(s, u, id, token, result.State == "Failed" ? "Failed" : "Unknown", null, result.ResourceId, result.Outcome, result.Cost, ct); return; }
        await Guard(s, u, row, false, ct); var info = await Renderer(snap.Profile.Configuration.Renderer).InspectAsync(result.Master, ct); if (!info.Playable || result.Mime != "video/mp4") throw new EvidenceBlockedException("PlayableOwnedMasterRequired"); var saved = await masters.PutAsync(Derived(id, "master"), result.Master, row.Actor, ct);
        await Command(s, u, Derived(id, "accepted-master"), "master", new { id, result.ResourceId, saved.Sha256 }, "Admin", async () => { var st = await db.WatchStages.SingleAsync(x => x.Id == id, ct); var current = await Production(s, u, row.Id, ct); if (current.State is "Cancelled" or "Withdrawn" || st.LeaseToken != token) return false; await Guard(s, u, current, false, ct); if (await db.WatchArtifacts.AnyAsync(x => x.StageId == id, ct)) return true; var reference = new CoreAssetReference { Id = Guid.NewGuid(), TenantId = s.TenantId, ContentRevisionId = current.CoreRevisionId, StorageAssetId = saved.Id, RightsStatus = "Owned" }; db.Assets.Add(reference); var artifact = new WatchArtifact { Id = Guid.NewGuid(), TenantId = s.TenantId, UniverseId = u, ProductionId = current.Id, StageId = id, AssetReferenceId = reference.Id, StorageAssetId = saved.Id, StorageOwner = row.Actor, Aspect = st.Kind[6..], Sha256 = saved.Sha256, Length = saved.Length }; artifact.SnapshotJson = Json(new WatchArtifactView(artifact.Id, artifact.Aspect, reference.Id, saved.Id, result.Mime, saved.Sha256, saved.Length, info.DurationSeconds, result.RendererVersion, result.Warnings)); db.WatchArtifacts.Add(artifact); st.State = "Accepted"; st.OutputJson = Json(new { artifact.Id, saved.Sha256 }); st.ExternalResourceId = result.ResourceId; st.ActualCost = result.Cost; st.LeaseToken = null; st.LeaseUntilUtc = null; return true; }, ct);
    }
    public async Task ControlAsync(CoreScope s, Guid u, Guid id, WatchControl r, CancellationToken ct)
    {
        if (r.Action == "Reconcile")
        { await Access(s, u, "Admin", ct); var prior = await db.WatchOperations.AsNoTracking().SingleOrDefaultAsync(x => x.TenantId == s.TenantId && x.OperationId == r.OperationId, ct); if (prior != null) { if (prior.Actor != s.Actor || prior.Kind != "reconcile" || prior.Fingerprint != EditorialBinding.Hash(new { u, request = new { id, r } })) throw new RuntimeConflictException("WATCH reconciliation replay differs."); if (await db.WatchOperations.AnyAsync(x => x.TenantId == s.TenantId && x.OperationId == Derived(r.OperationId, "resume"), ct)) return; } var row = await Production(s, u, id, ct); Expected(row, r.ExpectedRowVersion); var st = await db.WatchStages.AsNoTracking().Where(x => x.ProductionId == id && x.State == "Unknown" && x.Kind.StartsWith("Render")).OrderBy(x => x.Sequence).FirstOrDefaultAsync(ct) ?? throw new RuntimeConflictException("OriginalUnknownRendererStageRequired"); var token = Derived(r.OperationId, "reconcile-token"); await Command(s, u, r.OperationId, "reconcile", new { id, r }, "Admin", async () => { var stage = await db.WatchStages.SingleAsync(x => x.Id == st.Id, ct); stage.LeaseToken = token; stage.LeaseUntilUtc = DateTimeOffset.UtcNow.AddMinutes(5); return id; }, ct); var result = await Renderer(Read<WatchSnapshot>(row.SnapshotJson).Profile.Configuration.Renderer).ReconcileAsync(await RenderRequest(s, u, row, st, ct), st.ExternalResourceId, ct); await AcceptRender(s, u, st.Id, token, result, ct); if (result.State == "Completed") await Command(s, u, Derived(r.OperationId, "resume"), "resume-reconciled", new { id }, "Admin", async () => { var current = await Production(s, u, id, ct); if (current.State == "Failed" && await db.WatchStages.AnyAsync(x => x.Id == st.Id && x.State == "Accepted", ct)) current.State = "Running"; return id; }, ct); return; }
        await Command(s, u, r.OperationId, "control", new { id, r }, "Admin", async () => { var row = await Production(s, u, id, ct); Expected(row, r.ExpectedRowVersion); CoreRules.Text(r.EvidenceReference, 1000, "Recovery evidence"); if (r.Action == "Resume") { if (row.State != "Failed") throw new RuntimeConflictException("Only a known failed episode resumes."); if (await db.WatchStages.AnyAsync(x => x.ProductionId == id && x.State == "Unknown", ct)) throw new EvidenceBlockedException("ReconcileOriginalUncertainWorkBeforeResume"); await Guard(s, u, row, true, ct); foreach (var st in await db.WatchStages.Where(x => x.ProductionId == id && x.State == "Failed").ToListAsync(ct)) { st.State = "Pending"; st.Outcome = null; } row.State = "Running"; } else if (r.Action is "Cancel" or "Withdraw") { row.State = r.Action == "Cancel" ? "Cancelled" : "Withdrawn"; foreach (var st in await db.WatchStages.Where(x => x.ProductionId == id && x.State != "Accepted").ToListAsync(ct)) { st.State = "Cancelled"; st.LeaseToken = null; st.LeaseUntilUtc = null; } } else throw new RuntimeValidationException("Explicit WATCH recovery/control required."); return id; }, ct);
    }
    public async Task ReviewAsync(CoreScope s, Guid u, Guid id, WatchReview r, CancellationToken ct) => _ = await Command(s, u, r.OperationId, "episode-review", new { id, r }, "Review", async () => { var row = await Production(s, u, id, ct); Expected(row, r.ExpectedRowVersion); MediaRules.Attest(r.Mode, r.EvidenceReference); if (r.ReviewMinutes is < 1 or > 600 || r.Decision is not ("Approve" or "Reject" or "Withdraw")) throw new RuntimeValidationException("Record actual final review effort and decision."); if (r.Decision == "Approve") { if (row.State != "Review" || r.Deviations.Length > 0 || !await db.WatchStages.AnyAsync(x => x.ProductionId == id && x.Kind == "QA" && x.State == "Accepted", ct)) throw new EvidenceBlockedException("CorrectDeviationsAndPassQABeforeFinalApproval"); await Guard(s, u, row, false, ct); if (r.Mode == "Manual") { var snap = Read<WatchSnapshot>(row.SnapshotJson); if (snap.Profile.Capabilities.Qualification == "OfflineFixture") throw new EvidenceBlockedException("FixtureRendererCannotAcquirePublicQualificationByAttestation"); await Source(s, snap, "Publish", ct); await WatchFence.VideoRights(db, s, row, "Publish", ct); var timeline = Read<WatchTimeline>(row.TimelineJson!); foreach (var scene in timeline.Scenes) { await MediaRightsGuard.Assert(db, s, u, scene.Image.Id, "Publish", true, ct); await MediaRightsGuard.Assert(db, s, u, scene.Voice.Id, "Publish", true, ct); if (scene.Music != null) await MediaRightsGuard.Assert(db, s, u, scene.Music.Id, "Publish", true, ct); } } var approval = await db.WatchStages.SingleAsync(x => x.ProductionId == id && x.Kind == "Approval", ct); approval.State = "Accepted"; approval.OutputJson = Json(r); row.State = "Approved"; } else row.State = r.Decision == "Reject" ? "Rejected" : "Withdrawn"; row.ReviewJson = Json(r); row.ReviewMinutes += r.ReviewMinutes; return id; }, ct);
    public async Task<(byte[] Bytes, string Mime)> PreviewAsync(CoreScope s, Guid u, Guid artifact, CancellationToken ct)
    { await Access(s, u, "Read", ct); var a = await db.WatchArtifacts.AsNoTracking().SingleOrDefaultAsync(x => x.Id == artifact && x.TenantId == s.TenantId && x.UniverseId == u, ct) ?? throw new CoreAccessException(); var row = await Production(s, u, a.ProductionId, ct); await Guard(s, u, row, false, ct); foreach (var scene in Read<WatchTimeline>(row.TimelineJson!).Scenes) { await MediaRightsGuard.Assert(db, s, u, scene.Image.Id, "Reuse", true, ct); await MediaRightsGuard.Assert(db, s, u, scene.Voice.Id, "Reuse", true, ct); if (scene.Music != null) await MediaRightsGuard.Assert(db, s, u, scene.Music.Id, "Reuse", true, ct); } var bytes = await store.GetAsync(a.StorageAssetId, a.StorageOwner, ct) ?? throw new RuntimeConflictException("Owned WATCH master unavailable."); if (MediaRules.Hash(bytes) != a.Sha256) throw new RuntimeConflictException("Master checksum changed."); return (bytes, "video/mp4"); }
    public async Task<WatchExport> ExportAsync(CoreScope s, Guid u, Guid id, string purpose, CancellationToken ct)
    { if (purpose is not ("Export" or "Publish")) throw new RuntimeValidationException("Explicit WATCH export purpose required."); await Access(s, u, "Read", ct); var row = await Production(s, u, id, ct); if (row.State != "Approved") throw new EvidenceBlockedException("FinalEpisodeApprovalRequired"); await Guard(s, u, row, false, ct); await WatchFence.VideoRights(db, s, row, purpose, ct); if (purpose == "Publish") { if (row.ReviewJson == null || Read<WatchReview>(row.ReviewJson).Mode != "Manual") throw new EvidenceBlockedException("FixtureEpisodeCannotPublish"); await Source(s, Read<WatchSnapshot>(row.SnapshotJson), "Publish", ct); await WatchFence.AssertExport(db, s, row.CoreRevisionId, "Publish", ct); } foreach (var artifact in await db.WatchArtifacts.AsNoTracking().Where(x => x.ProductionId == id).ToArrayAsync(ct)) await PreviewAsync(s, u, artifact.Id, ct); var view = await InspectAsync(s, u, id, ct); return new(view, subtitles.Vtt(view.Timeline!.Captions), subtitles.Srt(view.Timeline.Captions)); }
